-- Milestone 7: unified inbox + leads/CRM
CREATE TABLE "ChannelConversation" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "integrationId" TEXT, "channel" TEXT NOT NULL, "externalContactId" TEXT NOT NULL, "contactName" TEXT, "contactPhone" TEXT, "customerId" TEXT, "leadId" TEXT, "status" TEXT NOT NULL DEFAULT 'open', "assignedUserId" TEXT, "unreadCount" INTEGER NOT NULL DEFAULT 0, "lastMessageAt" TIMESTAMP(3), "lastMessagePreview" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ChannelConversation_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ChannelConversation_organizationId_channel_externalContactId_key" ON "ChannelConversation"("organizationId","channel","externalContactId");
CREATE INDEX "ChannelConversation_organizationId_status_lastMessageAt_idx" ON "ChannelConversation"("organizationId","status","lastMessageAt");
CREATE TABLE "ChannelMessage" ("id" TEXT NOT NULL, "conversationId" TEXT NOT NULL, "direction" TEXT NOT NULL, "externalId" TEXT, "type" TEXT NOT NULL DEFAULT 'text', "content" TEXT, "mediaUrl" TEXT, "status" TEXT NOT NULL DEFAULT 'received', "error" TEXT, "sentByUserId" TEXT, "sentByAiDraft" BOOLEAN NOT NULL DEFAULT false, "platformTimestamp" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ChannelMessage_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ChannelMessage_conversationId_externalId_key" ON "ChannelMessage"("conversationId","externalId");
CREATE INDEX "ChannelMessage_conversationId_createdAt_idx" ON "ChannelMessage"("conversationId","createdAt");
CREATE TABLE "MessageDraft" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "conversationId" TEXT NOT NULL, "content" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'suggested', "provider" TEXT NOT NULL, "createdByUserId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "MessageDraft_pkey" PRIMARY KEY ("id"));
CREATE INDEX "MessageDraft_organizationId_conversationId_status_idx" ON "MessageDraft"("organizationId","conversationId","status");
CREATE TABLE "Lead" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "customerId" TEXT, "name" TEXT NOT NULL, "phone" TEXT, "email" TEXT, "source" TEXT NOT NULL DEFAULT 'manual', "stage" TEXT NOT NULL DEFAULT 'new', "valueMinor" BIGINT, "currency" TEXT NOT NULL DEFAULT 'BDT', "ownerUserId" TEXT, "notes" TEXT, "nextFollowUpAt" TIMESTAMP(3), "lastContactedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Lead_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Lead_organizationId_stage_idx" ON "Lead"("organizationId","stage");
CREATE INDEX "Lead_organizationId_phone_idx" ON "Lead"("organizationId","phone");
CREATE TABLE "LeadActivity" ("id" TEXT NOT NULL, "leadId" TEXT NOT NULL, "userId" TEXT, "type" TEXT NOT NULL, "content" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "LeadActivity_pkey" PRIMARY KEY ("id"));
CREATE INDEX "LeadActivity_leadId_createdAt_idx" ON "LeadActivity"("leadId","createdAt");
ALTER TABLE "ChannelConversation" ADD CONSTRAINT "ChannelConversation_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ChannelMessage" ADD CONSTRAINT "ChannelMessage_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "ChannelConversation"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "MessageDraft" ADD CONSTRAINT "MessageDraft_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "ChannelConversation"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Lead" ADD CONSTRAINT "Lead_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "LeadActivity" ADD CONSTRAINT "LeadActivity_leadId_fkey" FOREIGN KEY ("leadId") REFERENCES "Lead"("id") ON DELETE CASCADE ON UPDATE CASCADE;
